#![cfg(kani)]

// ============================================================================
// State model (derived from qedspec — no framework dependencies)
// ============================================================================

#[derive(Clone, Copy, PartialEq, Eq, kani::Arbitrary)]
enum Status {
    Uninitialized,
    Active,
}

#[derive(Clone, Copy)]
struct State {
    total: u64,
    rate: u64,
    status: Status,
}

// ============================================================================
// Property predicates (from qedspec `property` declarations)
// ============================================================================

/// rate_floor: s.rate > 0 ∨ s.total = 0
fn rate_floor(s: &State) -> bool {
    s.rate > 0 || s.total == 0
}

// ============================================================================
// Transition functions (from qedspec operations — effects + guards)
//
// Each returns true if the guard passes and the transition fires,
// false if the guard rejects the operation.
// ============================================================================

fn init_pool(s: &mut State, rate_in: u64) -> bool {
    if !(rate_in > 0) {
        return false;
    }
    if s.status != Status::Uninitialized {
        return false;
    }
    s.rate = rate_in;
    s.total = 0;
    s.status = Status::Active;
    true
}

fn deposit(s: &mut State, amount: u64) -> bool {
    if !(amount > 0) {
        return false;
    }
    if s.status != Status::Active {
        return false;
    }
    match s.total.checked_add(amount) {
        Some(__v) => s.total = __v,
        None => return false,
    }
    s.status = Status::Active;
    true
}

// ============================================================================
// Guard enforcement — transitions reject invalid inputs
// ============================================================================

#[kani::proof]
#[kani::unwind(2)]
#[kani::solver(cadical)]
fn verify_init_pool_rejects_invalid() {
    let mut s = State {
        total: kani::any(),
        rate: kani::any(),
        status: kani::any(),
    };
    kani::assume(s.status == Status::Uninitialized);
    let rate_in: u64 = kani::any();
    kani::assume(!(rate_in > 0));
    kani::cover!(true, "guard-violation domain is satisfiable");
    assert!(
        !init_pool(&mut s, rate_in),
        "init_pool must reject when guard is violated"
    );
}

#[kani::proof]
#[kani::unwind(2)]
#[kani::solver(cadical)]
fn verify_deposit_rejects_invalid() {
    let mut s = State {
        total: kani::any(),
        rate: kani::any(),
        status: kani::any(),
    };
    kani::assume(s.status == Status::Active);
    let amount: u64 = kani::any();
    kani::assume(!(amount > 0));
    kani::cover!(true, "guard-violation domain is satisfiable");
    assert!(
        !deposit(&mut s, amount),
        "deposit must reject when guard is violated"
    );
}

// ============================================================================
// Property preservation — invariants hold through all transitions
// ============================================================================

#[kani::proof]
#[kani::unwind(2)]
#[kani::solver(cadical)]
fn verify_init_pool_preserves_rate_floor() {
    let pre = State {
        total: 0,
        rate: 0,
        status: Status::Uninitialized,
    };
    let mut post = pre;
    let rate_in: u64 = kani::any();
    if init_pool(&mut post, rate_in) {
        assert!(rate_floor(&post), "rate_floor must hold after init_pool");
    }
}

#[kani::proof]
#[kani::unwind(2)]
#[kani::solver(cadical)]
fn verify_deposit_preserves_rate_floor() {
    let pre = State {
        total: kani::any(),
        rate: kani::any(),
        status: kani::any(),
    };
    kani::assume(pre.status == Status::Active);
    kani::assume(rate_floor(&pre));
    let mut post = pre;
    let amount: u64 = kani::any();
    if deposit(&mut post, amount) {
        assert!(rate_floor(&post), "rate_floor must hold after deposit");
    }
}

