#[kani::proof]
#[kani::unwind(2)]
#[kani::solver(cadical)]
fn verify_init_pool_effect_rate() {
    let mut s = State {
        total: 0,
        rate: 0,
        status: Status::Uninitialized,
    };
    let rate_in: u64 = kani::any();
    let pre_total = s.total;
    if init_pool(&mut s, rate_in) {
        assert!(s.rate == rate_in, "rate must equal rate_in");
    }
}

#[kani::proof]
#[kani::unwind(2)]
#[kani::solver(cadical)]
fn verify_init_pool_effect_total() {
    let mut s = State {
        total: 0,
        rate: 0,
        status: Status::Uninitialized,
    };
    let rate_in: u64 = kani::any();
    let pre_rate = s.rate;
    if init_pool(&mut s, rate_in) {
        assert!(s.total == 0, "total must equal 0");
    }
}

#[kani::proof]
#[kani::unwind(2)]
#[kani::solver(cadical)]
fn verify_deposit_effect_total() {
    let mut s = State {
        total: kani::any(),
        rate: kani::any(),
        status: kani::any(),
    };
    kani::assume(s.status == Status::Active);
    let amount: u64 = kani::any();
    let pre_total = s.total;
    let pre_rate = s.rate;
    if deposit(&mut s, amount) {
        assert!(
            s.total == pre_total.wrapping_add(amount),
            "total must increment by amount"
        );
        assert!(s.rate == pre_rate, "rate must not change");
    }
}

