#[kani::proof]
#[kani::unwind(2)]
#[kani::solver(cadical)]
fn verify_rate_floor_under_rate_change() {
    let mut s = State {
        total: kani::any(),
        rate: kani::any(),
        status: kani::any(),
    };
    kani::assume(rate_floor(&s));
    s.rate = kani::any();
    kani::assume(s.rate > 0);
    assert!(rate_floor(&s), "rate_floor must hold after rate_change");
}

#[kani::proof]
#[kani::unwind(2)]
#[kani::solver(cadical)]
fn verify_rate_floor_under_oracle_step() {
    let mut s = State {
        total: kani::any(),
        rate: kani::any(),
        status: kani::any(),
    };
    kani::assume(rate_floor(&s));
    let pre_oracle_price: u64 = kani::any();
    let post_oracle_price: u64 = kani::any();
    s.rate = kani::any();
    let post = &s;
    kani::assume(post.rate == post_oracle_price);
    kani::assume(post_oracle_price >= pre_oracle_price);
    assert!(rate_floor(&s), "rate_floor must hold after oracle_step");
}

